type OrderStatus = "pending" | "paid" | "shipped";

interface Order {
  id: string;
  total: number;
  status: OrderStatus;
}

const paidOrders = orders.filter((order: Order) => order.status === "paid");

async function reserveStock(sku: string, quantity: number): Promise<boolean> {
  const item = await inventory.findBySku(sku);
  if (!item || item.available < quantity) return false;
  await inventory.update(sku, { available: item.available - quantity });
  return true;
}

function calculateInvoice(lines: InvoiceLine[]): number {
  return lines.reduce((total, line) => {
    const subtotal = line.unitPrice * line.quantity;
    return total + subtotal * (1 - line.discount);
  }, 0);
}

