function calculateOrderTotal(array $items): float
{
    return array_reduce($items, function (float $total, array $item): float {
        return $total + $item['price'] * $item['quantity'];
    }, 0.0);
}

function reserveStock(array &$item, int $quantity): bool
{
    if ($quantity <= 0 || $item['available'] < $quantity) {
        return false;
    }
    $item['available'] -= $quantity;
    return true;
}
